"""Build a voice-matched question-insertion listening page from measured artifacts."""
import hashlib
from html import escape as e
import json
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs
from ami_pipeline import audio_pipeline, pipeline_styles

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'research/ami-question-audio'
URL='../research/ami-question-audio/'
NAMES={'qwen':'Qwen3-TTS 1.7B Base / vLLM-Omni','chatterbox':'Chatterbox English 500M','f5':'F5-TTS v1 Base'}

def p(text):return '<p>'+e(str(text))+'</p>'
def clock(t):return f'{int(t)//60:02d}:{t%60:05.2f}'
def player(path,label):return '<audio controls preload="none" aria-label="'+e(label)+'" src="'+URL+e(path)+'"></audio>'
def table(n,title,headers,rows):
 return '<div class="audio-table"><table><caption>Table '+str(n)+'. '+e(title)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def main():
 data=json.loads((DATA/'manifest.json').read_text());review=json.loads((DATA/'review.json').read_text());accounting=json.loads((DATA/'accounting.json').read_text());vc=json.loads((DATA/'vc-controls.json').read_text());second_asr={r['id']:r for r in review['whisper_after_matching']['records']}
 body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><main id="main"><div class="container">'+experiment_subtabs('ami-audio')
 body+='<header class="hero"><p class="eyebrow">AMI question audio · 20 October 2026</p><h1>Questions in the requester’s voice.</h1><p class="lede">Compare three open TTS models asking the same meeting-history questions as speakers B and C. Each clip pauses the original meeting, inserts a synthetic question and resumes the source audio.</p><div class="button-row"><a class="button primary" href="#listen">Listen to the insertions</a><a class="button" href="ami-questions.html">Text-question study</a><a class="button" href="'+URL+'manifest.json">Audio and timing manifest</a></div></header>'
 body+='<div class="callout amber"><strong>These questions were synthesized for this study.</strong>'+p('The original participants did not ask them in the source recording. Answer generation is deferred. Synthesis is prepared offline; this page does not demonstrate live TTS latency. Voice and environment scores are automated checks, with perceptual matching left for listening review.')+'</div>'
 body+=audio_pipeline()
 body+='<section><h2>What to listen for</h2>'+p('Start with F5-TTS: its selected outputs have the strongest held-out voice similarity for all three questions. This is an automated selection, not a listening verdict.')+p('Start with the original B and C excerpts in Figure 2, then compare the context clips in Figure 3. Listen for accent and voice identity, a conversational question contour, and a level or background change at the insertion. The speech label follows playback so the synthetic portion is unambiguous.')
 body+='<figure class="card"><figcaption><strong>Figure 2.</strong> Original AMI voice references. Conditioning uses only earlier speech; the separate comparison utterance is never used by the TTS models.</figcaption><div class="voice-grid">'
 for speaker in ['B','C']:
  primary=next(r for r in data['protocol']['references'] if r['id']==speaker+'-primary');held=next(r for r in data['protocol']['references'] if r['id']==speaker+'-heldout')
  body+='<div><h3>Original speaker '+speaker+'</h3>'+p('Conditioning utterance · '+clock(primary['source_start_seconds'])+'–'+clock(primary['source_end_seconds'])+' · individual '+data['protocol']['speaker_mapping'][speaker])+player(primary['headset'],'Original speaker '+speaker+' conditioning headset')+p(primary['text'])+'<details><summary>Same utterance in the meeting mix</summary>'+player(primary['mix'],'Original speaker '+speaker+' conditioning mix')+'</details>'+p('Independent original comparison · '+clock(held['source_start_seconds'])+'–'+clock(held['source_end_seconds']))+player(held['mix'],'Original speaker '+speaker+' independent comparison')+p(held['text'])+'</div>'
 body+='</div></figure></section><section id="listen"><h2>Listen to the paused insertions</h2>'+p('Figure 3 shows one automatically selected setting per model and question. The selection first checks the spoken wording, then uses similarity to an unused utterance of the requester. All selected clips use the same level and room-tone matching procedure. Original meeting samples before and after each insertion are copied exactly.')+'<figure><figcaption><strong>Figure 3.</strong> Short original context → synthetic requester question → resumed original audio. The amber timeline interval marks inserted audio, including short room-tone pads.</figcaption>'
 for q in data['protocol']['questions']:
  clips=sorted([c for c in data['clips'] if c['short_id']==q['short_id']],key=lambda c:['f5','qwen','chatterbox'].index(c['model']))
  body+='<article class="question-block" id="'+e(q['short_id'])+'"><h3>'+e(q['question'])+'</h3>'+p('Requester '+q['requester']+' → separate meeting assistant · source pause '+clock(q['source_time_seconds'])+' · '+q['id'])+'<div class="model-grid">'
  for c in clips:
   end=c['inserted_interval_end_seconds'];total=c['context_end_seconds']-c['context_start_seconds']+c['source_clock_shift_seconds'];begin=c['inserted_interval_start_seconds'];pct=100*begin/total;length=100*(end-begin)/total
   body+='<div class="card listen-card" data-start="'+str(begin)+'" data-end="'+str(end)+'" data-speech="'+str(c['synthetic_speech_playback_start_seconds'])+'"><h4>'+e(NAMES[c['model']])+'</h4><span class="tag">Synthetic voice '+c['requester']+'</span>'+player(c['injected_path'],q['short_id']+' '+c['model']+' context and synthetic question')+'<div class="clip-timeline" role="img" aria-label="Synthetic insertion starts '+f'{begin:.2f}'+' seconds into this clip"><span style="left:'+f'{pct:.4f}'+'%;width:'+f'{length:.4f}'+'%"></span></div><p class="playback-state" aria-live="polite">Original meeting</p><button class="button jump-question" type="button">Play from the question</button>'+p('Selected: '+c['setting']['id']+' · wording WER '+f"{100*c['asr']['wer']:.1f}%"+' · held-out speaker cosine '+f"{c['speaker_check']['target_cosine']:.3f}")+'<details><summary>Question alone and exact checks</summary><h5>With recording-level matching</h5>'+player(c['matched_path'],q['short_id']+' '+c['model']+' matched question only')+'<h5>Raw TTS output</h5>'+player(c['raw_path'],q['short_id']+' '+c['model']+' raw question only')+p('Parakeet ASR on matched audio: '+c['processed_asr']['text'])+p('Whisper-base on matched audio: '+second_asr[c['id']]['matched_path'])+p('Voice margin over the other requester: '+f"{c['speaker_check']['target_minus_other']:.3f}"+'. A cosine score does not establish perceived identity.')+p('Level adjustment '+f"{c['acoustics']['gain_db']:+.2f}"+' dB; no extra EQ. Source clock pauses for '+f"{c['source_clock_shift_seconds']:.2f}"+' s. Prefix/suffix PCM identity: verified.')+'</details></div>'
  body+='</div></article>'
 body+='</figure></section><section><h2>What was tuned and checked</h2>'+p(review['overview'])+p('Each model runs four configurations for each of three questions. The sweep compares headset versus mixed-channel conditioning, an alternate earlier utterance, and model-specific delivery controls. This is inference and reference tuning; no model weights were trained. Two VC controls are reported below and are excluded from the main replay.')
 body+=table(1,'Model choice and inference controls',['Model','Why test it','Tuned controls','License'],[[NAMES['qwen'],'Audio-and-text conditioning; optimized local inference','Reference/channel; temperature 0.9 vs 0.65; vLLM-Omni graphs','Apache 2.0'],[NAMES['chatterbox'],'Reference-conditioned English speech with delivery controls','Reference/channel; CFG 0.5 vs 0.3; exaggeration 0.5 vs 0.25; temperature','MIT'],[NAMES['f5'],'Flow-matching alternative with explicit reference transcript','Reference/channel; 32 vs 48 steps; guidance 2 vs 1.5; speed 1 vs 0.9','Code MIT; weights CC BY-NC 4.0']])
 body+=p('Original primary-versus-held-out utterance cosine is 0.735 for B and 0.669 for C. These values illustrate within-speaker variation; cosine is not an identity probability.')+p('Acoustic matching resamples to the source’s 16 kHz, matches active speech level, fills missing noise with a speech-free interval from the earlier meeting. A ±4 dB EQ trial made two F5 phrases less stable for a second ASR, so the main clips use no additional EQ. No room impulse response is estimated and no invented reverberation is added. This approximates the mixed-headset recording, rather than validating a physical room match.')
 body+='<h3>Voice-conversion control for speaker C</h3>'+p(vc['decision'])+p('Direct F5 cosine: '+f"{vc['direct_f5_cosine']:.3f}"+'. Both controls reuse the same Chatterbox checkpoint; they do not add a fourth TTS architecture.')
 for r in vc['records']:
  body+='<div class="card"><strong>F5 → Chatterbox VC · '+e(r['reference_id'])+'</strong>'+player(r['matched_path'],'Speaker C voice conversion '+r['reference_id'])+p('Held-out cosine '+f"{r['speaker_check']['target_cosine']:.3f}"+'; normalized Parakeet WER '+f"{100*r['asr']['wer']:.1f}%"+'. The ASR and cosine refer to the raw VC output; this player applies the same level and room-tone procedure.')+'</div>'
 body+='<details><summary>All tuning variants and measured checks</summary>'+table(2,'Unprocessed question outputs; WER is lower-is-better and voice cosine is higher-is-better',['Question','Model / setting','ASR WER','Voice cosine','Voice margin','Audio'],[[r['short_id'],r['model']+' / '+r['setting']['id'],f"{100*r['asr']['wer']:.1f}%",f"{r['speaker_check']['target_cosine']:.3f}",f"{r['speaker_check']['target_minus_other']:.3f}",r['path']] for r in data['candidates']])
 for r in data['candidates']:
  body+='<div class="tuning-clip"><strong>'+e(r['short_id']+' · '+r['model']+' · '+r['setting']['id'])+'</strong>'+player(r['path'],'Tuning '+r['short_id']+' '+r['model']+' '+r['setting']['id'])+p(r['asr']['text'])+'</div>'
 body+='</details>'+p(review['limitations'])+'</section><section><h2>Reproduction and resources</h2>'+p('A local full-meeting WAV and a 480 ms packet replay preserve the source timeline and insert only questions. The public page hosts short excerpts. No answering model or answer TTS runs in this study.')
 body+=table(3,'Actual GPU allocations, including failed startup attempts; CPU mixing/publication use zero GPUs',['Job','Task','GPUs / type / VRAM','Role and dependency','GPU hours'],[[r['job_id'],r['task'],str(r['gpus'])+' × '+r['gpu_type'],r['role'],f"{r['gpu_hours']:.5f}"] for r in accounting['jobs'] if r['gpus']])
 body+='<details><summary>Runtime repairs and exact local recipe</summary>'+p('The first Qwen attempt used the upstream offline example and produced failed outputs with a padded 2048-token prompt. The corrected caller supplies the reference codec-frame count used by the official serving implementation. All three successful sweeps ran on one L40S 48 GB each.')+'<ul><li><a href="'+URL+'source-ami_qwen_exact_prompt_launcher.py">Qwen prompt-length correction</a> · <a href="'+URL+'source-ami_qwen_tts_stages.yaml">vLLM stage settings</a></li><li><a href="'+URL+'source-ami_f5_pcm_launcher.py">F5 PCM decoder adapter</a> · <a href="'+URL+'source-repair_ami_tts_envs.sh">Chatterbox runtime and normal watermark dependency</a></li><li><a href="'+URL+'ami_qwen_tts-lock.txt">Qwen environment lock</a> · <a href="'+URL+'ami_chatterbox-lock.txt">Chatterbox lock</a> · <a href="'+URL+'ami_f5-lock.txt">F5 lock</a></li></ul>'+p('Two L40S devices reported uncorrectable ECC errors and were excluded. These failures are charged in Table 3. Failed generations and successful source files remain separate in the manifest; local launch snapshots preserve exact inputs.')+'</details>'
 body+=p('Total allocation: '+f"{accounting['total_gpu_hours']:.5f}"+' GPU hours. Measured maximum concurrent experiment GPUs: '+str(accounting['maximum_concurrent_gpus'])+'. Each job uses GPU 0 for all of its components. Independent evaluation runs ASR and the speaker encoder sequentially.')
 body+='<ul><li><a href="'+URL+'review.json">Content and audio audit</a></li><li><a href="'+URL+'accounting.json">Exact Slurm accounting and concurrency</a></li><li><a href="'+URL+'model-provenance.json">Pinned checkpoint revisions and hashes</a></li><li><a href="'+URL+'source-ami_tts_generate.py">Synthesis sweep</a>, <a href="'+URL+'source-mix_ami_question_audio.py">acoustic matching and splice code</a>, <a href="'+URL+'source-replay_ami_question_injection.py">packet replay</a></li></ul>'
 body+='<h3>Sources and attribution</h3>'+p('Original audio: AMI Meeting Corpus, EN2003a, speakers B/C; CC BY 4.0 current official release. New clips crop original audio and add synthetic speech and acoustic processing. Speaker C’s corrected audio channel is Headset-3; formal job roles are not supplied for this meeting.')+'<ul><li><a href="https://groups.inf.ed.ac.uk/ami/corpus/license.shtml">AMI corpus license</a> · <a href="https://groups.inf.ed.ac.uk/ami/AMICorpusMirror/amicorpus/EN2003a/audio/">Official recording directory</a></li><li><a href="https://github.com/QwenLM/Qwen3-TTS">Qwen3-TTS official code and cloning instructions</a> · <a href="https://github.com/vllm-project/vllm-omni/tree/v0.16.0/examples/offline_inference/qwen3_tts">vLLM-Omni inference</a></li><li><a href="https://github.com/resemble-ai/chatterbox">Chatterbox reference and guidance controls</a></li><li><a href="https://github.com/SWivid/F5-TTS">F5-TTS official code</a> · <a href="https://huggingface.co/SWivid/F5-TTS">Noncommercial pretrained weights</a></li><li><a href="https://huggingface.co/speechbrain/spkrec-ecapa-voxceleb">Independent ECAPA speaker encoder</a> · <a href="https://huggingface.co/nvidia/parakeet-tdt-0.6b-v2">Independent Parakeet ASR</a></li></ul></section></div></main>'
 style='''.voice-grid,.model-grid{display:grid;gap:18px;grid-template-columns:repeat(2,minmax(0,1fr))}.model-grid{grid-template-columns:repeat(3,minmax(0,1fr))}audio{display:block;width:100%;max-width:100%;margin:12px 0}.question-block{margin:26px 0 42px}.listen-card{min-width:0}.listen-card h4{font-size:1.08rem;margin-top:0}.audio-table{overflow:auto}th,td{vertical-align:top}.clip-timeline{height:12px;background:var(--border,#ccc);position:relative;border-radius:8px;overflow:hidden}.clip-timeline span{background:#dba438;position:absolute;height:100%}.playback-state{font-weight:650;min-height:1.5em}.playback-state.synthetic{color:#aa6500}.tuning-clip{padding:14px 0;border-bottom:1px solid var(--border,#aaa)}figcaption{margin:10px 0 18px;line-height:1.6}.button{white-space:normal}details{margin-top:16px}h5{font-size:1rem}@media(max-width:960px){.model-grid{grid-template-columns:1fr}}@media(max-width:650px){.voice-grid{grid-template-columns:1fr}.card{padding:16px}}'''
 style+=pipeline_styles()
 script='''document.querySelectorAll('.listen-card').forEach(card=>{let a=card.querySelector('audio'),state=card.querySelector('.playback-state'),start=+card.dataset.start,end=+card.dataset.end;function mark(){let t=a.currentTime,s=t>=start&&t<end;state.textContent=s?'Synthetic requester question':t>=end?'Original meeting resumed':'Original meeting';state.classList.toggle('synthetic',s)}a.addEventListener('timeupdate',mark);a.addEventListener('seeked',mark);card.querySelector('.jump-question').onclick=async()=>{if(a.readyState===0){a.load();await new Promise((resolve,reject)=>{a.addEventListener('loadedmetadata',resolve,{once:true});a.addEventListener('error',reject,{once:true})})}a.currentTime=Math.max(0,+card.dataset.speech-.1);await a.play()}});document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(b!==a)b.pause()})));'''
 css=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
 page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Listen to synthetic AMI questions in the original requester’s voice, with original voice references and paused audio insertions."><meta name="color-scheme" content="light dark"><title>AMI question audio · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css?v='+css+'"><style>'+style+'</style></head><body><a class="skip-link" href="#main">Skip to audio study</a>'+body+'<script>'+script+'</script></body></html>'
 (ROOT/'experiments/ami-question-audio.html').write_text(page)
 collection=ROOT/'experiments/index.html';text=collection.read_text()
 if 'id="ami-audio-card"' not in text and 'href="ami-question-audio.html"' not in text:
  card='<article class="card" id="ami-audio-card"><span class="tag">AMI question audio</span><h3>Questions in the requester’s voice</h3><p>Three TTS models, original speaker references, acoustic tuning and short paused question insertions. Answer generation is deferred.</p><p><a class="button" href="ami-question-audio.html">Listen to the voice comparisons</a></p></article>'
  collection.write_text(text.replace('<div class="card-grid">','<div class="card-grid">'+card,1))
 print('Rendered',len(data['clips']),'listening comparisons')

if __name__=='__main__':main()
